const updateLocalTask = `-- name: UpdateLocalTask :execrows
UPDATE tasks SET
    title       = ?,
    description = ?,
    status      = ?,
    start_date  = ?,
    due_date    = ?
WHERE id = ? AND originated = 'local'
`

type UpdateLocalTaskParams struct {
	Title       string
	Description string
	Status      string
	StartDate   sql.NullTime
	DueDate     sql.NullTime
	ID          string
}

func (q *Queries) UpdateLocalTask(ctx context.Context, arg UpdateLocalTaskParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateLocalTask,
		arg.Title,
		arg.Description,
		arg.Status,
		arg.StartDate,
		arg.DueDate,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateTodo = `-- name: UpdateTodo :execrows
UPDATE todos SET
    description  = ?1,
    note         = ?2,
    is_done      = ?3,
    completed_at = CASE WHEN ?3 THEN COALESCE(completed_at, ?4) END,
    start_date   = ?5,
    end_date     = ?6
WHERE id = ?7
`

type UpdateTodoParams struct {
	Description string
	Note        string
	IsDone      bool
	CompletedAt sql.NullTime
	StartDate   sql.NullString
	EndDate     sql.NullString
	ID          int64
}

// A todo that stays done keeps its completed_at.
func (q *Queries) UpdateTodo(ctx context.Context, arg UpdateTodoParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateTodo,
		arg.Description,
		arg.Note,
		arg.IsDone,
		arg.CompletedAt,
		arg.StartDate,
		arg.EndDate,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const upsertServiceDeskRequest = `-- name: UpsertServiceDeskRequest :exec
INSERT INTO service_desk_requests (
    issue_key, title, status, status_category, created_at, status_at
) VALUES (
    ?, ?, ?, ?, ?, ?
)
ON CONFLICT (issue_key) DO UPDATE SET
    title           = excluded.title,
    status          = excluded.status,
    status_category = excluded.status_category,
    created_at      = excluded.created_at,
    status_at       = excluded.status_at
`

type UpsertServiceDeskRequestParams struct {
	IssueKey       string
	Title          string
	Status         string
	StatusCategory string
	CreatedAt      time.Time
	StatusAt       time.Time
}

func (q *Queries) UpsertServiceDeskRequest(ctx context.Context, arg UpsertServiceDeskRequestParams) error {
	_, err := q.db.ExecContext(ctx, upsertServiceDeskRequest,
		arg.IssueKey,
		arg.Title,
		arg.Status,
		arg.StatusCategory,
		arg.CreatedAt,
		arg.StatusAt,
	)
	return err
}

